import apiClient from './client'

export type UserRole = 'admin' | 'viewer'

export interface UserRead {
  id: number
  username: string
  email?: string
  role: UserRole
  is_active: boolean
  created_at: string
}

export interface UserCreate {
  username: string
  email?: string
  password: string
  role?: UserRole
  is_active?: boolean
}

export interface UserUpdate {
  email?: string
  password?: string
  role?: UserRole
  is_active?: boolean
}

export interface Page<T> {
  items: T[]
  total: number
  page: number
  page_size: number
}

export async function getUsers(page = 1, pageSize = 20): Promise<Page<UserRead>> {
  const response = await apiClient.get<Page<UserRead>>('/v1/users', {
    params: { page, page_size: pageSize },
  })
  return response.data
}

export async function createUser(data: UserCreate): Promise<UserRead> {
  const response = await apiClient.post<UserRead>('/v1/users', data)
  return response.data
}

export async function updateUser(id: number, data: UserUpdate): Promise<UserRead> {
  const response = await apiClient.put<UserRead>(`/v1/users/${id}`, data)
  return response.data
}

export async function deleteUser(id: number): Promise<void> {
  await apiClient.delete(`/v1/users/${id}`)
}
