<template>
  <div class="page-user-management">
    <div class="page-header">
      <h2>{{ t('settings.users.title') }}</h2>
      <el-button type="primary" @click="onCreate">{{ t('settings.users.createUser') }}</el-button>
    </div>

    <el-card>
      <DataTable
        :data="users"
        :loading="loading"
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :total="total"
        server-side
        @page-change="loadUsers"
        @size-change="loadUsers"
      >
        <el-table-column prop="id" label="ID" width="80" />
        <el-table-column prop="username" :label="t('common.username')" min-width="140" />
        <el-table-column prop="email" :label="t('common.email')" min-width="180" />
        <el-table-column prop="role" :label="t('common.role')" width="120" />
        <el-table-column prop="is_active" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.is_active ? 'success' : 'info'" size="small">
              {{ row.is_active ? t('common.enabled') : t('common.disabled') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="created_at" :label="t('common.createdAt')" width="180" />
        <el-table-column :label="t('common.actions')" width="240" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="onEdit(row)">
              {{ t('common.edit') }}
            </el-button>
            <el-button link type="primary" size="small" @click="onToggleStatus(row)">
              {{ row.is_active ? t('common.disable') : t('common.enable') }}
            </el-button>
            <ConfirmButton
              :title="t('settings.users.confirmDelete')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? t('settings.users.editTitle') : t('settings.users.createTitle')"
      width="520px"
      :close-on-click-modal="false"
      @closed="resetForm"
    >
      <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
        <el-form-item v-if="!isEdit" :label="t('common.username')" prop="username">
          <el-input v-model="form.username" :placeholder="t('settings.users.usernamePlaceholder')" />
        </el-form-item>
        <el-form-item v-if="isEdit" :label="t('common.username')">
          <span>{{ editingUser?.username }}</span>
        </el-form-item>
        <el-form-item :label="t('common.email')" prop="email">
          <el-input v-model="form.email" :placeholder="t('settings.users.emailPlaceholder')" />
        </el-form-item>
        <el-form-item :label="t('common.password')" :prop="isEdit ? undefined : 'password'">
          <el-input
            v-model="form.password"
            type="password"
            :placeholder="isEdit ? t('settings.users.passwordPlaceholderEdit') : t('settings.users.passwordPlaceholderCreate')"
            show-password
          />
        </el-form-item>
        <el-form-item :label="t('common.role')" prop="role">
          <el-select v-model="form.role" :placeholder="t('settings.users.rolePlaceholder')" style="width: 100%">
            <el-option :label="t('settings.users.roleAdmin')" value="admin" />
            <el-option :label="t('settings.users.roleViewer')" value="viewer" />
          </el-select>
        </el-form-item>
        <el-form-item v-if="isEdit" :label="t('common.status')">
          <el-switch
            v-model="form.is_active"
            :active-text="t('common.enable')"
            :inactive-text="t('common.disable')"
          />
        </el-form-item>
      </el-form>

      <template #footer>
        <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" :loading="submitting" @click="onSubmit">
          {{ isEdit ? t('common.save') : t('common.create') }}
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { createUser, deleteUser, getUsers, updateUser, type UserRead } from '@/api/users'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import DataTable from '@/components/common/DataTable.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const users = ref<UserRead[]>([])
const loading = ref(false)
const page = ref(1)
const pageSize = ref(20)
const total = ref(0)
const dialogVisible = ref(false)
const submitting = ref(false)
const isEdit = ref(false)
const editingUser = ref<UserRead | null>(null)
const formRef = ref<FormInstance>()

const form = ref({
  username: '',
  email: '',
  password: '',
  role: 'viewer' as 'admin' | 'viewer',
  is_active: true,
})

const rules: FormRules = {
  username: [{ required: true, message: () => t('settings.users.usernameRequired'), trigger: 'blur' }],
  email: [{ type: 'email', message: () => t('settings.users.emailInvalid'), trigger: 'blur' }],
  password: [{ required: true, message: () => t('settings.users.passwordRequired'), trigger: 'blur' }],
  role: [{ required: true, message: () => t('settings.users.roleRequired'), trigger: 'change' }],
}

async function loadUsers() {
  loading.value = true
  try {
    const result = await getUsers(page.value, pageSize.value)
    users.value = result.items
    total.value = result.total
  } catch (error) {
    showError(error, t('settings.users.loadFailed'))
  } finally {
    loading.value = false
  }
}

function resetForm() {
  form.value = { username: '', email: '', password: '', role: 'viewer', is_active: true }
  editingUser.value = null
  formRef.value?.resetFields()
}

function onCreate() {
  isEdit.value = false
  editingUser.value = null
  form.value = { username: '', email: '', password: '', role: 'viewer', is_active: true }
  dialogVisible.value = true
}

function onEdit(row: UserRead) {
  isEdit.value = true
  editingUser.value = row
  form.value = {
    username: row.username,
    email: row.email || '',
    password: '',
    role: row.role,
    is_active: row.is_active,
  }
  dialogVisible.value = true
}

async function onToggleStatus(row: UserRead) {
  try {
    await updateUser(row.id, { is_active: !row.is_active })
    ElMessage.success(t('common.statusUpdated'))
    loadUsers()
  } catch (error) {
    showError(error, t('common.updateStatusFailed'))
  }
}

async function onDelete(row: UserRead) {
  try {
    await deleteUser(row.id)
    ElMessage.success(t('settings.users.userDeleted'))
    loadUsers()
  } catch (error) {
    showError(error, t('settings.users.deleteUserFailed'))
  }
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    if (isEdit.value && editingUser.value) {
      const payload: {
        email?: string
        password?: string
        role?: 'admin' | 'viewer'
        is_active?: boolean
      } = {
        email: form.value.email || undefined,
        role: form.value.role,
        is_active: form.value.is_active,
      }
      if (form.value.password) {
        payload.password = form.value.password
      }
      await updateUser(editingUser.value.id, payload)
      ElMessage.success(t('settings.users.userUpdated'))
    } else {
      await createUser({
        username: form.value.username,
        email: form.value.email || undefined,
        password: form.value.password,
        role: form.value.role,
      })
      ElMessage.success(t('settings.users.userCreated'))
    }
    dialogVisible.value = false
    loadUsers()
  } catch (error) {
    showError(error, isEdit.value ? t('settings.users.updateFailed') : t('settings.users.createFailed'))
  } finally {
    submitting.value = false
  }
}

onMounted(() => {
  loadUsers()
})
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.pagination-bar {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}
</style>
